import { test, expect } from '@playwright/test';

test.describe('Locked Out User Login Error', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
  });

  test('should display error message when locked out user attempts to login', async ({ page }) => {
    // Fill in the username field with locked_out_user
    await page.getByLabel('Username').fill('locked_out_user');

    // Fill in the password field with secret_sauce
    await page.getByLabel('Password').fill('secret_sauce');

    // Click the login button
    await page.getByRole('button', { name: /login/i }).click();

    // Verify we remain on the login page
    await expect(page).toHaveURL('https://www.saucedemo.com/');

    // Verify the error container is visible
    const errorContainer = page.locator('[data-test="error"]');
    await expect(errorContainer).toBeVisible();

    // Verify the error message contains the expected text
    await expect(errorContainer).toContainText('Sorry, this user has been locked out');
  });

  test('should keep user on login page after locked out error', async ({ page }) => {
    // Fill in credentials for locked out user
    await page.getByLabel('Username').fill('locked_out_user');
    await page.getByLabel('Password').fill('secret_sauce');

    // Click login button
    await page.getByRole('button', { name: /login/i }).click();

    // Verify the login form is still present
    const usernameInput = page.getByLabel('Username');
    await expect(usernameInput).toBeVisible();

    // Verify the password input is still present
    const passwordInput = page.getByLabel('Password');
    await expect(passwordInput).toBeVisible();

    // Verify we haven't been redirected to the inventory page
    await expect(page).not.toHaveURL(/inventory/);
  });
});
